INSERT INTO metric_definitions (id, code, name, description, unit, category, higher_is_better) VALUES ('549ca419-da7c-5d5f-be67-f29607e72087', 'tvl_usd', 'Total value locked (USD)', 'TVL across the project''s DeFi ecosystem, in USD (DefiLlama).', 'USD', 'chain', TRUE) ON CONFLICT (id) DO NOTHING;
