INSERT INTO score_definitions (id, code, name, description, scale_min, scale_max, kind) VALUES ('b1b19bb0-bce0-5f12-b18d-7206941a4bd5', 'attention', 'Attention', 'Mindshare: mentions, search, social. Phase 2 — no reliable source in v0.1.', 0, 10, 'supporting') ON CONFLICT (id) DO NOTHING;
INSERT INTO score_definitions (id, code, name, description, scale_min, scale_max, kind) VALUES ('31eed236-dc9b-54e2-bad5-adb34b011264', 'development', 'Development', 'Core-protocol development pace. Single-component in v0.1; expands with the GitHub adapter in Phase 2.', 0, 10, 'supporting') ON CONFLICT (id) DO NOTHING;
INSERT INTO score_definitions (id, code, name, description, scale_min, scale_max, kind) VALUES ('6b4178c9-eaef-5b4c-b71f-5cc42e846af6', 'evidence_confidence', 'Evidence Confidence', 'How much the numbers can be trusted, given data completeness and source quality.', 0, 100, 'supporting') ON CONFLICT (id) DO NOTHING;
INSERT INTO score_definitions (id, code, name, description, scale_min, scale_max, kind) VALUES ('470ca602-51ac-59bb-a1f8-650a12dcf1e3', 'execution_evidence', 'Execution Evidence', 'Is the project measurably moving toward its potential? An evidence score — NOT a probability. No calibrated probabilities until historical backtesting exists (Phase 2).', 0, 10, 'dimension') ON CONFLICT (id) DO NOTHING;
INSERT INTO score_definitions (id, code, name, description, scale_min, scale_max, kind) VALUES ('73f05bc5-7e90-5fab-9573-1746e9593ee9', 'prove_it_age_years', 'Prove-It Age', 'Years since network launch. Not a countdown — there is no deadline. The question is: after X years, how much closer is the thesis to fulfilled?', 0, 100, 'supporting') ON CONFLICT (id) DO NOTHING;
INSERT INTO score_definitions (id, code, name, description, scale_min, scale_max, kind) VALUES ('25619fb1-0e18-52f6-9a4e-e7c6471e05bd', 'reality', 'Reality', 'Genuine utility demonstrated today: willingness to pay, capital committed, thesis milestones actually achieved. Market cap is NEVER an input — price is not evidence of utility.', 0, 10, 'dimension') ON CONFLICT (id) DO NOTHING;
INSERT INTO score_definitions (id, code, name, description, scale_min, scale_max, kind) VALUES ('23342ee8-1cce-5504-99ae-f93e4d69971d', 'reflexivity_risk', 'Reflexivity / Failure Risk', 'How dependent the current value/ecosystem is on continued speculation, incentives, issuance, or belief. High score = high dependence. Characteristics are measured; projects are never labeled.', 0, 10, 'dimension') ON CONFLICT (id) DO NOTHING;
INSERT INTO score_definitions (id, code, name, description, scale_min, scale_max, kind) VALUES ('4d4d49d7-5c1a-5477-b689-9e11c9b8ad28', 'subsidy_dependence', 'Subsidy Dependence', 'What happens to activity when incentives end (30/90/180-day post-incentive retention). No reliable source in v0.1.', 0, 10, 'supporting') ON CONFLICT (id) DO NOTHING;
INSERT INTO score_definitions (id, code, name, description, scale_min, scale_max, kind) VALUES ('427bb6af-89e6-59f3-836f-d32ede1d92fb', 'token_necessity', 'Token Necessity', 'If the token disappeared, could essentially the same protocol continue functioning? Analyst-assessed, versioned, rationale published.', 0, 10, 'analyst') ON CONFLICT (id) DO NOTHING;
INSERT INTO score_definitions (id, code, name, description, scale_min, scale_max, kind) VALUES ('2365b412-8ff2-5241-a6fc-78d42c8f8e49', 'token_value_capture', 'Token Value Capture', 'As usage grows, does the token capture economic value? Assessed against the mechanism checklist (fees, burns, staking, collateral, settlement demand). Successful protocol != valuable token until demonstrated.', 0, 10, 'analyst') ON CONFLICT (id) DO NOTHING;
INSERT INTO score_definitions (id, code, name, description, scale_min, scale_max, kind) VALUES ('dcb4bda4-697a-58db-9582-716266a95b2f', 'world_impact_potential', 'World Impact Potential', 'If the thesis succeeds, how consequential? Potential, not prediction. Analyst-assessed per thesis category, rationale published.', 0, 10, 'analyst') ON CONFLICT (id) DO NOTHING;
INSERT INTO score_components (id, score_id, code, name, description) VALUES ('6e508ef4-6c88-5d48-96cc-69f17400cc24', '31eed236-dc9b-54e2-bad5-adb34b011264', 'developer_activity', 'Developer activity', 'Core-protocol development pace. CoinGecko developer_data in v0.1 (spotty upstream); dedicated GitHub adapter is Phase 2.') ON CONFLICT (id) DO NOTHING;
INSERT INTO score_components (id, score_id, code, name, description) VALUES ('c7ca71e0-5399-546a-a3dc-ea0ba1b4f253', '470ca602-51ac-59bb-a1f8-650a12dcf1e3', 'developer_activity', 'Developer activity', 'Core-protocol development pace. CoinGecko developer_data in v0.1 (spotty upstream); dedicated GitHub adapter is Phase 2.') ON CONFLICT (id) DO NOTHING;
INSERT INTO score_components (id, score_id, code, name, description) VALUES ('1dbb2328-6625-556c-9672-1eb87acfea1f', '470ca602-51ac-59bb-a1f8-650a12dcf1e3', 'milestone_velocity', 'Milestone velocity', 'Thesis milestones achieved in the trailing 3 years, scaled: 2+ milestones -> 10. Momentum, not just level.') ON CONFLICT (id) DO NOTHING;
