INSERT INTO score_components (id, score_id, code, name, description) VALUES ('35cfd9ac-8afe-50ec-b833-3ead29f4b4a9', '25619fb1-0e18-52f6-9a4e-e7c6471e05bd', 'capital_committed', 'Capital committed', 'How much capital is committed onchain (TVL). Log-scaled: $10M -> 0, $100B -> 10.') ON CONFLICT (id) DO NOTHING;
