INSERT INTO project_theses (id, project_id, methodology_version_id, thesis_text, measurable_success, evidence_url) VALUES ('61501676-76ae-54e2-8f68-5b22823f7043', 'a9b173a8-b996-5a1b-aa94-e8f987299124', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'Become a globally held, politically neutral monetary asset — digital gold — that preserves purchasing power over long horizons and settles finality without trusted intermediaries.', 'Sustained demand as a long-duration store of value across cycles: growing holder base, deep liquid markets, institutional/sovereign allocation, and fee-paying settlement demand independent of speculation.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO project_theses (id, project_id, methodology_version_id, thesis_text, measurable_success, evidence_url) VALUES ('8817e923-e765-55fb-b76d-40f127a4eb12', '15de9695-1aa6-54a2-80b9-79029c6f79b3', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'Become the dominant programmable settlement and execution layer for decentralized applications and tokenized value — the base layer others build financial infrastructure on.', 'Majority share of onchain economic activity (fees, DEX volume, stablecoin settlement); enterprises and institutions building on or settling via Ethereum; sustained developer dominance.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO project_theses (id, project_id, methodology_version_id, thesis_text, measurable_success, evidence_url) VALUES ('439604fb-aecb-510b-b5f1-ba9cb6d931d9', '9f1a1d05-cd5b-5fbd-80a0-a993f66e00a5', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'Become the high-throughput execution layer for consumer-scale crypto applications — fast, cheap settlement for onchain trading, payments, and DePIN.', 'Sustained high-retention consumer application usage (trading, payments, DePIN) with activity persisting independent of token incentives.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO project_theses (id, project_id, methodology_version_id, thesis_text, measurable_success, evidence_url) VALUES ('8effa749-c4a9-54ab-aee6-2e04e319e001', '2cb6fd6a-1754-5e88-b408-3805d17281d2', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'Become the bridge asset and settlement rail for cross-border institutional payments — the currency banks use to move value between corridors.', 'Banks and payment providers using XRP itself (not just Ripple messaging software) for settlement at meaningful, recurring volume.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO project_theses (id, project_id, methodology_version_id, thesis_text, measurable_success, evidence_url) VALUES ('a05d7daf-3e8c-5331-8de0-7dcbbd620830', '182d6ffa-b26c-56a6-aa8a-a08b691d8d73', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'Become the standard decentralized oracle infrastructure that smart contracts depend on for market data and offchain computation.', 'Dominant share of oracle-secured value across chains, with node operators earning sustainable fee revenue from data consumers and major enterprise integrations.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO project_theses (id, project_id, methodology_version_id, thesis_text, measurable_success, evidence_url) VALUES ('38064eaa-ba31-5af3-bd35-c775dc5261db', 'fa865acf-744a-509b-b53a-193a50e40d48', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'Become a peer-reviewed, formally-verified smart contract platform for global financial and identity infrastructure — the academically rigorous alternative.', 'Meaningful developer and user adoption of Cardano smart contracts, with real-world identity or financial deployments operating at scale.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO project_theses (id, project_id, methodology_version_id, thesis_text, measurable_success, evidence_url) VALUES ('f38a91b5-942c-513a-8c9e-48e537ee9cb7', '556a2851-e33f-541b-9d72-e40790d1c30d', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'Be the dominant dollar-settlement instrument of crypto: a token redeemable 1:1 for USD, trusted enough that exchanges, traders, and real-world users settle in it instead of banks.', 'Peg holds through market stress with redemptions honored at par; supply grows across cycles; reserve attestations continue; settlement use extends beyond speculation.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO project_theses (id, project_id, methodology_version_id, thesis_text, measurable_success, evidence_url) VALUES ('7ff04cf1-8ac1-5c33-a1f4-59088ca039e1', 'ea0f65ac-c6bc-5db4-ac5e-e3e523e756db', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'Be the gas and coordination token of the Binance ecosystem: BNB Chain''s execution layer plus fee discounts and launchpad access on the world''s largest exchange.', 'BNB Chain sustains top-tier fee revenue and active addresses across cycles; BNB demand tied to chain usage and venue utility rather than speculation alone.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO project_theses (id, project_id, methodology_version_id, thesis_text, measurable_success, evidence_url) VALUES ('72337ec3-1b5a-50de-a822-58eec23e44e8', '61b4c628-1b5f-5298-ac37-fcb402db804f', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'Be the regulated, redeemable dollar token: 1:1 USD redeemability with audited reserves, trusted for onchain settlement and corporate treasury use.', 'Peg holds through stress; redemptions honored at par; monthly attestations continue; corporate and DeFi settlement share grows.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO project_theses (id, project_id, methodology_version_id, thesis_text, measurable_success, evidence_url) VALUES ('b2a2e4a2-4b48-5030-8675-5d87a4143fdc', 'b39f6d29-7aea-517b-877c-89fc8763ec82', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'Be the cheapest high-throughput settlement chain for dollar stablecoins: dominate USDT transfers with near-zero fees.', 'TRON carries the plurality of USDT transfer volume; chain fee revenue persists across cycles; usage is payments-driven, not speculative.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO project_theses (id, project_id, methodology_version_id, thesis_text, measurable_success, evidence_url) VALUES ('16e14e4e-9292-5bb6-9174-39f5c04a4c33', '0fd0a2b0-3f9d-5e41-8202-99173b11a92e', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'Be private sound money: Bitcoin-like scarcity with shielded transactions that make every coin fungible.', 'Shielded pool grows; survives market cycles with development continuing; remains the reference privacy coin with real transaction demand.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO project_theses (id, project_id, methodology_version_id, thesis_text, measurable_success, evidence_url) VALUES ('7c84efc9-f1a8-5589-b04b-81f6795c3f8d', '3f87705b-636e-5db6-812c-c5df3b21b748', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'Be the decentralized venue that takes perpetuals volume from centralized exchanges: CEX-grade performance with onchain settlement, plus a general L1 (HyperEVM).', 'Sustained top share of onchain perps volume; fee revenue competitive with centralized venues; HyperEVM attracts independent developers.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO project_theses (id, project_id, methodology_version_id, thesis_text, measurable_success, evidence_url) VALUES ('923406d0-e9cc-5e6c-b7c2-4a1ccb2626d6', 'ecb72594-3380-53fb-96da-ca5432b5998b', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'Be the internet''s money by culture: a fun, cheap, inflationary coin that survives every cycle on community and memetic persistence.', 'Survives cycles with an active chain and holders; accepted for payments by major merchants; remains top-10 without a development roadmap.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO project_theses (id, project_id, methodology_version_id, thesis_text, measurable_success, evidence_url) VALUES ('f82c9c62-9317-5654-95f8-8bb57b1fb7f9', 'e98d902d-1f40-5b3f-bb21-2b77ffdf6640', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'Be fungible digital cash: private by default, so every coin is equal and censorship-resistant.', 'Remains the most-used privacy coin; survives exchange delistings with peer-to-peer liquidity; development continues.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO project_theses (id, project_id, methodology_version_id, thesis_text, measurable_success, evidence_url) VALUES ('3634c5c0-936f-5176-a3df-1ed172cbf511', '798474a5-3ce6-5e4b-b35a-aa7680112a90', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'Be permissionless infrastructure for prediction markets: anyone can create, trade, and resolve markets, with AI-assisted resolution and private markets.', 'Sustained market-creation and trading volume independent of token incentives; resolution quality trusted by market creators; repeat enterprise/DAO users.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO project_theses (id, project_id, methodology_version_id, thesis_text, measurable_success, evidence_url) VALUES ('65c3a042-d337-51ac-ae6f-2139e71ddc49', '878a21cf-148f-54ba-a57e-cdcebe4a1e12', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'Be the decentralized dollar: a crypto-collateralized, redeemable stablecoin with no centralized issuer to seize or censor.', 'Peg holds through stress; DAI-to-USDS migration completes; the Sky Savings Rate attracts sticky deposits; decentralized collateral mix persists.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO project_theses (id, project_id, methodology_version_id, thesis_text, measurable_success, evidence_url) VALUES ('551940c0-e2a1-5425-aaef-ebc3cdae9b62', '638daaeb-2b54-5275-be65-7fe1b03714b1', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'Be the fee token of the Bitfinex ecosystem: trading-fee discounts funded by a contractual monthly buyback-and-burn from iFinex revenue.', 'Buybacks execute monthly from gross revenue; fee-payment demand persists in line with Bitfinex volume; supply declines per the whitepaper schedule.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO project_theses (id, project_id, methodology_version_id, thesis_text, measurable_success, evidence_url) VALUES ('901ff9b4-bf0e-543a-9f3c-30fa13f41d7d', '347edbe4-82ac-55a7-aef2-c854e558f276', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'Be the low-cost settlement rail for cross-border payments: near-free transfers with 5-second finality connecting banks, money transmitters, and wallets.', 'Production payment corridors with named institutions; recurring settlement volume independent of speculation; corridor count grows.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO project_theses (id, project_id, methodology_version_id, thesis_text, measurable_success, evidence_url) VALUES ('540317d4-785d-55a8-acf5-6b1b969fb6bb', '0bbaa824-8123-5adb-8493-8f6084c50522', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'Represent home-equity line-of-credit debt as onchain tokens: enforceable claims on real borrower payments, originated and serviced on blockchain rails (Provenance).', 'Sustained origination volume; secondary liquidity for the tokens; loans perform (low defaults); legal enforceability of the onchain claim tested and upheld.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO project_theses (id, project_id, methodology_version_id, thesis_text, measurable_success, evidence_url) VALUES ('f8d0d14b-8c9f-5ea5-b83d-c46a406f594c', '2ac405b8-e1c8-5eb5-b2f9-d3cba085a15a', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'Be the utility token of the WhiteBIT exchange and Whitechain: staking tiers, fee discounts, and ecosystem perks that retain traders.', 'Sustained staking and fee-payment demand correlated with WhiteBIT/Whitechain activity; token held by active users, not just speculators.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('5d6faf9c-b6de-5b59-ab0e-175345bfd0ff', 'a9b173a8-b996-5a1b-aa94-e8f987299124', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_necessity', 10, 'The token IS the monetary asset. There is no Bitcoin protocol without BTC; security, settlement, and the store-of-value thesis are all denominated in it.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('a592a955-e3a5-550f-b50e-4909f973b8be', 'a9b173a8-b996-5a1b-aa94-e8f987299124', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_value_capture', 6.5, 'No cash flows, no burn, no staking. Capture is purely monetary premium on a credibly fixed 21M supply — works only if the SoV thesis holds.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('0106aeaa-c39d-51ba-9e10-340584fcc104', 'a9b173a8-b996-5a1b-aa94-e8f987299124', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'world_impact_potential', 9, 'A successful neutral global monetary asset would be among the most consequential financial developments in a century. Highest-impact category in the taxonomy.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('7cbc0507-aefd-5beb-a936-ebe9c441b938', '15de9695-1aa6-54a2-80b9-79029c6f79b3', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_necessity', 9, 'ETH is required to pay gas for all execution and to stake for network security. The protocol cannot function without a native fee/staking asset; only the ticker could theoretically change.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('22a0a229-e177-5f10-8b16-cf80c3da24ff', '15de9695-1aa6-54a2-80b9-79029c6f79b3', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_value_capture', 7.5, 'EIP-1559 fee burn plus staking yield give direct value linkage, but L2s siphon execution and fee revenue is far below the 2021 peak. Capture is real but diluted versus the thesis.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('4afaf0d0-d596-5b3f-ab88-229e1bc48e88', '15de9695-1aa6-54a2-80b9-79029c6f79b3', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'world_impact_potential', 9, 'The dominant programmable settlement layer for tokenized global finance would be foundational infrastructure — comparable to the early internet''s TCP/IP layer.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('9920537c-917c-56d8-ba70-6941245d8675', '9f1a1d05-cd5b-5fbd-80a0-a993f66e00a5', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_necessity', 9, 'SOL pays all transaction fees and secures the network via staking. No SOL, no Solana.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('7c7dc3b6-5a9e-5122-96da-405737ca3100', '9f1a1d05-cd5b-5fbd-80a0-a993f66e00a5', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_value_capture', 6.5, 'Fees are intentionally tiny (a design goal), so capture leans on staking yield funded partly by issuance — dilutive. MEV adds some. Weaker direct linkage than ETH''s burn.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('9516e77c-7a5a-5eb8-bbfb-444b795f1799', '9f1a1d05-cd5b-5fbd-80a0-a993f66e00a5', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'world_impact_potential', 7.5, 'A successful consumer-scale execution layer would be major financial infrastructure, but the thesis is narrower than Ethereum''s base-layer ambition.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('59fc650b-b137-5edd-86e7-d3459df13f22', '2cb6fd6a-1754-5e88-b408-3805d17281d2', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_necessity', 6, 'XRP is the ledger''s native bridge asset and spam deterrent, but Ripple''s payment products have historically worked with minimal XRP usage; institutions can and do settle without it.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('df8fc570-61f7-5489-8030-983f246faee7', '2cb6fd6a-1754-5e88-b408-3805d17281d2', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_value_capture', 4, 'Negligible fee burn, no staking, large escrow overhang (tens of billions XRP released programmatically). Capture is almost entirely speculative premium.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('ca01d30d-b17c-5d30-adf2-25c5bf1717b3', '2cb6fd6a-1754-5e88-b408-3805d17281d2', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'world_impact_potential', 7, 'Capturing a share of global cross-border settlement would be highly consequential, but the thesis is narrower than a monetary asset or general execution layer.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('587ba256-896c-5ea5-80dc-41e1d5bed2ad', '182d6ffa-b26c-56a6-aa8a-a08b691d8d73', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_necessity', 8, 'Node operator payments, collateral, and staking are LINK-denominated by protocol design. A different token is conceivable but the cryptoeconomics are built around LINK.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('841b91b9-8132-547e-89e3-ef96bda88693', '182d6ffa-b26c-56a6-aa8a-a08b691d8d73', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_value_capture', 5.5, 'Staking and explicit fee payments exist (Economics 2.0, BUILD/SCALE), but realized fee revenue remains small relative to FDV; most historical node payment was subsidized.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('fadf3561-1ce7-5f7e-b123-01f26715fa34', '182d6ffa-b26c-56a6-aa8a-a08b691d8d73', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'world_impact_potential', 6.5, 'Critical middleware for tokenized finance, but middleware: the largest value accrues to the applications and assets above it, not the oracle layer.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('6b02fdf3-c07b-5b08-9964-63625e926b96', 'fa865acf-744a-509b-b53a-193a50e40d48', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_necessity', 9, 'ADA pays fees and secures the network via proof-of-stake delegation. No ADA, no Cardano.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('d58aafa5-a0b9-50e7-b5b8-ef1e0cecd4b8', 'fa865acf-744a-509b-b53a-193a50e40d48', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_value_capture', 5.5, 'Staking yield exists but is funded substantially by reserves/issuance; user-paid fee demand is small, so the fee-driven linkage is weak.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('9d4ccd33-a682-5bc5-92a1-37e4a460d39c', 'fa865acf-744a-509b-b53a-193a50e40d48', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'world_impact_potential', 7.5, 'Same category as Ethereum/Solana (execution layer), so the ceiling is comparable — assessed slightly below ETH given later start and narrower differentiation.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('f822019a-6423-5e8d-9112-664ccd79d14b', '556a2851-e33f-541b-9d72-e40790d1c30d', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_necessity', 10, 'The token IS the product. There is no Tether without USDT; issuance, redemption, and settlement are all denominated in it.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('02fe4bd3-206e-5821-8cc9-c0876a66e902', '556a2851-e33f-541b-9d72-e40790d1c30d', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_value_capture', 1, 'By design the token does not appreciate: 1 USDT targets $1. All economic value accrues to the issuer via reserve yield, not to holders.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('efe060ed-f64e-58fb-8385-26e5a98df29c', '556a2851-e33f-541b-9d72-e40790d1c30d', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'world_impact_potential', 7.5, 'If USDT becomes the default dollar rail for trade settlement outside the banking system, it is systemically consequential: a private dollar network at internet scale.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('77594997-6f6e-5ad5-baf4-ae296c655fbf', 'ea0f65ac-c6bc-5db4-ac5e-e3e523e756db', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_necessity', 8, 'BNB Chain requires BNB for gas; the chain cannot run without it. Exchange-utility functions (discounts, launchpad) could in principle be cash-denominated.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('30d4bdee-2af5-523a-89b2-b4123f9fb588', 'ea0f65ac-c6bc-5db4-ac5e-e3e523e756db', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_value_capture', 7.5, 'Auto-Burn destroys supply quarterly tied to chain activity; gas demand plus launchpad/venue demand create structural buy pressure.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('cb27ef70-4a7d-5dea-b47d-e5396e53e738', 'ea0f65ac-c6bc-5db4-ac5e-e3e523e756db', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'world_impact_potential', 7.5, 'A top-3 smart-contract chain plus the largest exchange''s utility token; success means a parallel financial infrastructure at global scale.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('ffdd55b0-c038-5a0d-9e53-309b76a19077', '61b4c628-1b5f-5298-ac37-fcb402db804f', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_necessity', 10, 'The token is the product. There is no USDC without the token; issuance, redemption, and settlement are all denominated in it.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('faf366bb-ce28-5298-9675-eadb69e09fb4', '61b4c628-1b5f-5298-ac37-fcb402db804f', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_value_capture', 1, 'By design the token does not appreciate: 1 USDC targets $1. Economic value accrues to the issuer (Circle) via reserve yield, not to holders.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('4bb3def8-5e26-5a2c-b0af-b2b343f8d97c', '61b4c628-1b5f-5298-ac37-fcb402db804f', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'world_impact_potential', 7, 'A regulated dollar rail could become default onchain cash for institutions and fintechs — the compliant counterpart to USDT''s offshore dollar.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('1ba3e348-e9ea-597b-bd32-8b366c3298a4', 'b39f6d29-7aea-517b-877c-89fc8763ec82', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_necessity', 8, 'The bandwidth/energy resource model requires TRX; the chain cannot run without it. Most usage is USDT transfer, which could in principle move chains.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('5a0cd445-08da-54a5-94c7-130f1012f8f5', 'b39f6d29-7aea-517b-877c-89fc8763ec82', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_value_capture', 6, 'Fee burns and staking rewards; value tied to stablecoin-transfer demand rather than speculation, but concentrated in one use case.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('9ce255ec-a8db-5ee8-9f0e-e82112a2a851', 'b39f6d29-7aea-517b-877c-89fc8763ec82', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'world_impact_potential', 6, 'The dominant stablecoin-transfer chain is meaningful payment infrastructure, but a narrow moat: if fees rise or a cheaper rail wins, the thesis erodes.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('1c2ee757-51b9-597c-acde-4972ab432e46', '0fd0a2b0-3f9d-5e41-8202-99173b11a92e', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_necessity', 10, 'The token IS the monetary asset. There is no Zcash protocol without ZEC; privacy, settlement, and the SoV thesis are all denominated in it.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('6cbb0052-896a-5084-8ee1-48d4254315a9', '0fd0a2b0-3f9d-5e41-8202-99173b11a92e', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_value_capture', 5, 'Fixed 21M supply; capture is purely monetary premium on the privacy-SoV thesis, which competes with Monero and with transparent chains plus mixers.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('8a0ed7c6-4446-5ea7-96ab-15bf1896f8db', '0fd0a2b0-3f9d-5e41-8202-99173b11a92e', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'world_impact_potential', 6.5, 'Fungible private money is a deep human need; success means a parallel cash system that survives state-level pressure.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('9b735b92-50d8-5455-84a9-8647bb3c0c47', '3f87705b-636e-5db6-812c-c5df3b21b748', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_necessity', 8, 'HYPE is gas for HyperEVM and staked for consensus; the chain cannot run without it. The perps DEX itself could settle in other collateral.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('73db1a25-c9b7-5367-b70c-9fffe92f65d5', '3f87705b-636e-5db6-812c-c5df3b21b748', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_value_capture', 7, 'The Assistance Fund uses protocol fees for HYPE buybacks; staking yields from fees. Capture is real but young and concentrated in perps volume.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('43f2bb4d-8a21-55db-b454-1a16e80bac61', '3f87705b-636e-5db6-812c-c5df3b21b748', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'world_impact_potential', 7.5, 'Displacing centralized perps venues would be the largest DeFi value-capture event to date: the first onchain venue to beat CEXs at their own game.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('c5225657-ebb3-519a-957e-68f64080c6ee', 'ecb72594-3380-53fb-96da-ca5432b5998b', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_necessity', 10, 'The token IS the monetary asset. There is no Dogecoin protocol without DOGE.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('aa8d545f-61e7-5f66-8430-8d13d591c602', 'ecb72594-3380-53fb-96da-ca5432b5998b', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_value_capture', 5, 'No supply cap and no burn; capture is purely monetary premium resting entirely on cultural persistence — the weakest monetary moat in the set.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('303c0ca3-466e-5c5d-ae02-5472bff8b718', 'ecb72594-3380-53fb-96da-ca5432b5998b', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'world_impact_potential', 6, 'A culturally-anchored global tipping currency is a real, if narrow, monetary success: proof that money can run on memes.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('84cbd777-2818-50f4-9bad-37c6bc0c98ce', 'e98d902d-1f40-5b3f-bb21-2b77ffdf6640', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_necessity', 10, 'The token IS the monetary asset. There is no Monero protocol without XMR.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('def66606-4743-5209-af67-de5fb6ce43f3', 'e98d902d-1f40-5b3f-bb21-2b77ffdf6640', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_value_capture', 5.5, 'Tail emission funds security indefinitely; monetary premium tied to privacy demand, which persists but is capped by regulatory exclusion.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('0eae1ce1-b1aa-5237-b210-c2e0d561726a', 'e98d902d-1f40-5b3f-bb21-2b77ffdf6640', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'world_impact_potential', 6, 'Private digital cash is a deep need; success means surviving state-level pressure as the hardest money to censor.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('090b63b2-5480-5467-9f86-fd21e389d289', '798474a5-3ce6-5e4b-b35a-aa7680112a90', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_necessity', 6, 'Governance plus fee/buyback utility; the protocol could resolve markets without the token, but tokenomics fund growth and align creators.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('fd90d7fa-58bf-5ed4-8831-fe80d5d0690e', '798474a5-3ce6-5e4b-b35a-aa7680112a90', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_value_capture', 5, 'Buyback-and-burn ties the token to protocol revenue per the whitepaper; unproven at scale and the DAO is not yet live.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('b8d8ab3d-6ea2-591b-9bd6-ca86c3678c50', '798474a5-3ce6-5e4b-b35a-aa7680112a90', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'world_impact_potential', 6.5, 'Decentralized prediction markets are a large potential market; success means rivaling centralized incumbents (Polymarket, Kalshi) on neutral rails.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('65171b72-afa0-53a1-ac5b-ebd81ee23853', '878a21cf-148f-54ba-a57e-cdcebe4a1e12', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_necessity', 9, 'The token is the product; governance is separated into SKY. There is no USDS system without the USDS token.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('2c3913c3-6318-5d2a-bb8d-e42fb49d6a2a', '878a21cf-148f-54ba-a57e-cdcebe4a1e12', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_value_capture', 1, 'By design the token does not appreciate: 1 USDS targets $1. Value accrues to SKY holders and the protocol, not USDS holders.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('9fac4a27-49d9-5021-a8af-d7ebe042a840', '878a21cf-148f-54ba-a57e-cdcebe4a1e12', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'world_impact_potential', 6.5, 'A decentralized dollar at scale is a major crypto-native achievement: censorship-resistant dollars without a bank.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('05fe3ab9-977e-5239-b5d0-b127b83858a4', '638daaeb-2b54-5275-be65-7fe1b03714b1', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_necessity', 3, 'A centralized exchange can discount fees in cash; LEO is a loyalty mechanism, not a protocol requirement. Triggers the token-necessity gate.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('77409bd6-dddf-51d6-a3da-d261d588d0d1', '638daaeb-2b54-5275-be65-7fe1b03714b1', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_value_capture', 4, 'Contractual buyback-and-burn from iFinex gross revenue is a real mechanism, but capture depends entirely on one venue''s fortunes (and is gate-capped).', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('cbad6c61-75d8-53d2-81a1-939ec5549c3b', '638daaeb-2b54-5275-be65-7fe1b03714b1', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'world_impact_potential', 3.5, 'A successful exchange loyalty token is a business win for one venue, not world-changing infrastructure.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('e8240dea-eb45-5f9a-8f8f-6a7d7bb8dc2d', '347edbe4-82ac-55a7-aef2-c854e558f276', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_necessity', 8, 'XLM is the bridge asset and anti-spam mechanism; the rail needs a native asset, though corridors increasingly settle in fiat-backed stablecoins.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('5bdff160-7c36-5060-b629-b0d09d1095d1', '347edbe4-82ac-55a7-aef2-c854e558f276', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_value_capture', 5, 'Minimal fee burn; value rests on bridge-asset demand and corridor growth, not on cash flows to holders.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('e1d1e7c1-fa25-5b09-9ad8-7d11c14e71a7', '347edbe4-82ac-55a7-aef2-c854e558f276', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'world_impact_potential', 6.5, 'Displacing correspondent banking in target corridors would be major financial infrastructure: cheaper remittances at global scale.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('88b68ef8-6bdd-5d7a-ab4d-48cf931b7b3e', '0bbaa824-8123-5adb-8493-8f6084c50522', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_necessity', 7, 'The token is the onchain claim instrument; the debt exists legally without it, but onchain transfer, settlement, and composability need the token.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('f673709e-ffc7-5802-9f7c-73f58040f784', '0bbaa824-8123-5adb-8493-8f6084c50522', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_value_capture', 4, 'Value is the debt claim itself plus coupon; no protocol-level accrual beyond the underlying loan economics.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('e894d2a8-11da-5536-a79e-643f7403a56f', '0bbaa824-8123-5adb-8493-8f6084c50522', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'world_impact_potential', 5.5, 'Tokenized private credit is a large addressable market; success means a working template for onchain real-world assets.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('4ae27ffb-2faa-5170-95ee-1b918c052cd7', '2ac405b8-e1c8-5eb5-b2f9-d3cba085a15a', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_necessity', 3, 'A centralized exchange can discount fees in cash; WBT is a loyalty and staking mechanism, not a protocol requirement. Triggers the token-necessity gate.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('0785ebee-07ad-5a96-ab9a-2393a08ed200', '2ac405b8-e1c8-5eb5-b2f9-d3cba085a15a', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'token_value_capture', 3, 'Staking tiers and burn programs exist, but capture depends entirely on one venue''s fortunes (and is gate-capped).', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO project_assessments (id, project_id, methodology_version_id, key, value, rationale, evidence_url, assessed_at) VALUES ('46811b25-f7be-512d-9df2-dc694be41cb7', '2ac405b8-e1c8-5eb5-b2f9-d3cba085a15a', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'world_impact_potential', 3.5, 'A successful exchange loyalty token is a business win for one venue, not world-changing infrastructure.', NULL, '2026-09-20') ON CONFLICT (id) DO NOTHING;
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('d56e954e-bade-5395-9361-b40eca777c9f', '74fc1c2d-d637-5b9c-9008-f0dea152083e', '8ac63e2e-b79c-592a-bde2-886c1543cdbd', 0, 'Functional network exists', 'Mainnet producing blocks and accepting contract deployments. Block explorer or client release notes.') ON CONFLICT (id) DO NOTHING;
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('255f63e7-8407-5082-a229-f94e66cb66ee', '74fc1c2d-d637-5b9c-9008-f0dea152083e', '8ac63e2e-b79c-592a-bde2-886c1543cdbd', 1, 'Independent developers and users', 'Third-party developers deploying contracts; non-team user transactions visible onchain. DApp listings, explorer activity.') ON CONFLICT (id) DO NOTHING;
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('a7fd55cf-9a6d-5ae5-9e36-e3d1b26dd3a1', '74fc1c2d-d637-5b9c-9008-f0dea152083e', '8ac63e2e-b79c-592a-bde2-886c1543cdbd', 2, 'Meaningful recurring fee revenue', 'Trailing-30d user-paid fees (DefiLlama or equivalent) at a level that would rank the chain among top fee-generating networks; fees paid by end users, not validator self-dealing.') ON CONFLICT (id) DO NOTHING;
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('eb9abb2b-026f-54a4-a64b-19b2a709c1eb', '74fc1c2d-d637-5b9c-9008-f0dea152083e', '8ac63e2e-b79c-592a-bde2-886c1543cdbd', 3, 'Usage persists without heavy incentives', 'Onchain activity and fee revenue persist through a >12-month drawdown or after major incentive programs end, without collapsing >80%.') ON CONFLICT (id) DO NOTHING;
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('69ab6864-17ce-5524-b06e-7fa97967d4a0', '74fc1c2d-d637-5b9c-9008-f0dea152083e', '8ac63e2e-b79c-592a-bde2-886c1543cdbd', 4, 'External institutions operationally depend on it', 'Named institutions running production workloads that depend on the chain (settlement, tokenized assets, enterprise apps) — live operations, not pilots or announcements.') ON CONFLICT (id) DO NOTHING;
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('2016afe6-9015-50a0-a86d-c620d100fdd4', '74fc1c2d-d637-5b9c-9008-f0dea152083e', '8ac63e2e-b79c-592a-bde2-886c1543cdbd', 5, 'Dominant execution layer', 'The chain is the default settlement/execution venue for its category by multiple independent measures (fees, developer share, tokenized value).') ON CONFLICT (id) DO NOTHING;
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('e5bbfa78-e529-564f-b546-e0a2e48c808a', '74fc1c2d-d637-5b9c-9008-f0dea152083e', '2824e0d9-96a7-5100-a813-a2124e7be9b2', 0, 'Functional network exists', 'Genesis block / network launch; blocks propagating.') ON CONFLICT (id) DO NOTHING;
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('1387499a-e702-57f0-8da6-6d26849d5045', '74fc1c2d-d637-5b9c-9008-f0dea152083e', '2824e0d9-96a7-5100-a813-a2124e7be9b2', 1, 'Independent users hold and transact', 'Non-trivial holder base, exchange listings, peer-to-peer transfers beyond the founding team.') ON CONFLICT (id) DO NOTHING;
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('6c0d22e8-2865-538d-906a-50bc0efe9189', '74fc1c2d-d637-5b9c-9008-f0dea152083e', '2824e0d9-96a7-5100-a813-a2124e7be9b2', 2, 'Survives a full market cycle intact', 'A >70% price drawdown occurs while onchain holder count, hash rate/security budget, and development do not collapse.') ON CONFLICT (id) DO NOTHING;
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('567303cc-70d1-5e3f-95fa-f25e38635b28', '74fc1c2d-d637-5b9c-9008-f0dea152083e', '2824e0d9-96a7-5100-a813-a2124e7be9b2', 3, 'Institutional allocation as treasury/reserve asset', 'Public companies, funds, or sovereigns disclose the asset on balance sheets or in regulated investment products.') ON CONFLICT (id) DO NOTHING;
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('32a83243-7c83-5f03-9759-df1ec15e90a9', '74fc1c2d-d637-5b9c-9008-f0dea152083e', '2824e0d9-96a7-5100-a813-a2124e7be9b2', 4, 'Unit of account / widespread medium of exchange', 'Priced and lent against broadly; used as a unit of account in real commerce beyond niche merchants.') ON CONFLICT (id) DO NOTHING;
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('5914ed15-4aca-5894-8533-cac5e7d0acb4', '74fc1c2d-d637-5b9c-9008-f0dea152083e', '2824e0d9-96a7-5100-a813-a2124e7be9b2', 5, 'Global monetary asset', 'Central banks or sovereign wealth funds hold it as a reserve asset class alongside gold/FX reserves.') ON CONFLICT (id) DO NOTHING;
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('385f254d-cf04-5f62-a5f1-39df27c47958', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'dec908e5-5aa2-54a6-8de0-0a5cd444c7a4', 0, 'Functional oracle network exists', 'Decentralized oracle network live, publishing price/data feeds consumed onchain.') ON CONFLICT (id) DO NOTHING;
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('f7c112e3-6cf5-5a06-9c82-ce87b0a2b6b7', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'dec908e5-5aa2-54a6-8de0-0a5cd444c7a4', 1, 'Independent protocols consume feeds', 'Third-party protocols integrating feeds for production use (lending, derivatives, stablecoins).') ON CONFLICT (id) DO NOTHING;
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('7ebd323d-62c1-5d08-8c37-acf60ae4b7d8', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'dec908e5-5aa2-54a6-8de0-0a5cd444c7a4', 2, 'Meaningful fee revenue from data consumers', 'Sustained fee payments from data consumers to node operators/stakers, visible in protocol economics disclosures.') ON CONFLICT (id) DO NOTHING;
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('9298f81b-9286-5a01-ba2b-0751c97b0462', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'dec908e5-5aa2-54a6-8de0-0a5cd444c7a4', 3, 'Dominant share of oracle-secured value', 'Clear majority share of oracle-secured onchain value across chains; competitors have not displaced it over a full cycle.') ON CONFLICT (id) DO NOTHING;
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('9a538574-02e2-5c52-8bad-854646771897', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'dec908e5-5aa2-54a6-8de0-0a5cd444c7a4', 4, 'Institutions operationally depend on the feeds', 'Banks, market infrastructure, or enterprises using the feeds in production systems — live operations, not pilots.') ON CONFLICT (id) DO NOTHING;
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('077caea0-8811-5427-9b7d-de356bae2786', '74fc1c2d-d637-5b9c-9008-f0dea152083e', 'dec908e5-5aa2-54a6-8de0-0a5cd444c7a4', 5, 'Standard oracle infrastructure', 'The network is the default oracle layer for tokenized global finance across asset classes.') ON CONFLICT (id) DO NOTHING;
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('19e3287f-b64c-538f-9385-068f86791111', '74fc1c2d-d637-5b9c-9008-f0dea152083e', '43e6624c-f303-50e1-9996-19937fbc4c19', 0, 'Instrument exists and functions', 'Token live; transfers, redemptions, or utility working onchain or via the issuer. Contract/explorer or issuer docs.') ON CONFLICT (id) DO NOTHING;
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('cb30157a-8629-5adf-94cf-16d66f016dd9', '74fc1c2d-d637-5b9c-9008-f0dea152083e', '43e6624c-f303-50e1-9996-19937fbc4c19', 1, 'Independent users', 'Holders/users beyond the issuer; exchange listings; third-party integrations.') ON CONFLICT (id) DO NOTHING;
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('58f01d5b-23b8-5219-86ed-20738a43f802', '74fc1c2d-d637-5b9c-9008-f0dea152083e', '43e6624c-f303-50e1-9996-19937fbc4c19', 2, 'Meaningful recurring function', 'The instrument''s stated function used at scale: redemptions honored at par, fee-payment demand, debt serviced, markets resolved.') ON CONFLICT (id) DO NOTHING;
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('56681ad3-4922-59b3-9653-00abf2d9b349', '74fc1c2d-d637-5b9c-9008-f0dea152083e', '43e6624c-f303-50e1-9996-19937fbc4c19', 3, 'Function survives stress', 'Peg defended through market stress, or function persists through a full market cycle without breaking.') ON CONFLICT (id) DO NOTHING;
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('293bf3bc-e3cc-5ad8-ace4-a3d895444126', '74fc1c2d-d637-5b9c-9008-f0dea152083e', '43e6624c-f303-50e1-9996-19937fbc4c19', 4, 'External institutions operationally depend on it', 'Named institutions (treasuries, corporates, regulated products) depend on the instrument in production.') ON CONFLICT (id) DO NOTHING;
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('5e35dd43-c980-5459-806b-a6b45078b53e', '74fc1c2d-d637-5b9c-9008-f0dea152083e', '43e6624c-f303-50e1-9996-19937fbc4c19', 5, 'Dominant instrument in its niche', 'Default instrument in its category by multiple independent measures.') ON CONFLICT (id) DO NOTHING;
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('2a83e4cb-6f20-580f-9114-7c5b4d8bda20', '74fc1c2d-d637-5b9c-9008-f0dea152083e', '79a43c1f-d952-579c-90c5-8c4a346a13a1', 0, 'Functional network exists', 'Ledger live and settling payment transactions.') ON CONFLICT (id) DO NOTHING;
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('8b8c5843-09e3-5dce-90d9-abaeb8f232eb', '74fc1c2d-d637-5b9c-9008-f0dea152083e', '79a43c1f-d952-579c-90c5-8c4a346a13a1', 1, 'Independent users transact', 'Payments by users beyond the founding team; wallet/exchange support.') ON CONFLICT (id) DO NOTHING;
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('4a6aeb57-335d-5faf-ba63-485b4d3940b5', '74fc1c2d-d637-5b9c-9008-f0dea152083e', '79a43c1f-d952-579c-90c5-8c4a346a13a1', 2, 'Meaningful recurring settlement volume', 'Recurring cross-border settlement volume attributable to the rail, disclosed by operators or visible onchain, sustained >6 months.') ON CONFLICT (id) DO NOTHING;
INSERT INTO milestone_definitions (id, methodology_version_id, thesis_category_id, level, title, evidence_requirements) VALUES ('56f7e207-6da7-52fa-8549-626d36e0c1bf', '74fc1c2d-d637-5b9c-9008-f0dea152083e', '79a43c1f-d952-579c-90c5-8c4a346a13a1', 3, 'Volume persists without issuer subsidies', 'Volume persists after issuer incentives, rebates, or subsidized corridors end.') ON CONFLICT (id) DO NOTHING;
